spec.section:
# policy-snapshot.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$defs": {
    "effectiveGrant": {
      "additionalProperties": false,
      "properties": {
        "authority_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "capability": {
          "minLength": 1,
          "type": "string"
        },
        "class": {
          "enum": [
            "use",
            "grant_use",
            "meta_grant",
            "create"
          ]
        },
        "expires_at": {
          "format": "date-time",
          "type": [
            "string",
            "null"
          ]
        },
        "grant_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "lineage": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "origin": {
          "enum": [
            "vp_configured",
            "director_grant",
            "manager_grant"
          ]
        },
        "resource_scope": {
          "items": {
            "type": "string"
          },
          "type": "array"
        }
      },
      "required": [
        "class",
        "capability",
        "resource_scope",
        "origin",
        "grant_id",
        "lineage"
      ],
      "type": "object"
    },
    "resync": {
      "additionalProperties": false,
      "properties": {
        "atomicity": {
          "const": "one_snapshot_revision_or_no_write"
        },
        "enabled": {
          "type": "boolean"
        },
        "last_actor": {
          "type": [
            "string",
            "null"
          ]
        },
        "last_approval_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "last_from_rev": {
          "minimum": 1,
          "type": [
            "integer",
            "null"
          ]
        },
        "last_reason": {
          "type": [
            "string",
            "null"
          ]
        },
        "last_to_rev": {
          "minimum": 1,
          "type": [
            "integer",
            "null"
          ]
        },
        "scope": {
          "enum": [
            "current_policy_within_vp_pool"
          ]
        }
      },
      "required": [
        "enabled",
        "scope",
        "atomicity",
        "last_actor"
      ],
      "type": "object"
    }
  },
  "$id": "https://coding-hermes.local/chd32/schemas/policy-snapshot.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "agent_id": {
      "minLength": 1,
      "type": "string"
    },
    "bond_id": {
      "minLength": 1,
      "type": "string"
    },
    "captured_at": {
      "format": "date-time",
      "type": "string"
    },
    "effective_policy_rev": {
      "minimum": 1,
      "type": "integer"
    },
    "fork_mode": {
      "enum": [
        "preserve_parent_snapshot",
        "current_policy"
      ]
    },
    "fork_point_seq": {
      "minimum": 0,
      "type": [
        "integer",
        "null"
      ]
    },
    "grants": {
      "items": {
        "$ref": "#/$defs/effectiveGrant"
      },
      "type": "array"
    },
    "host_id": {
      "pattern": "^host-[a-z0-9-]+$",
      "type": "string"
    },
    "parent_bond_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "parent_session_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "policy_owner": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "policy_rev": {
      "minimum": 1,
      "type": "integer"
    },
    "principal_id": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "profile_id": {
      "not": {
        "const": "default"
      },
      "pattern": "^pf-[a-z0-9-]+$",
      "type": "string"
    },
    "profile_ref": {
      "pattern": "^/chd/credentials/[A-Za-z0-9._/-]+$",
      "type": "string"
    },
    "resync": {
      "$ref": "#/$defs/resync"
    },
    "session_id": {
      "minLength": 1,
      "type": "string"
    },
    "snapshot_id": {
      "pattern": "^sp-[A-Za-z0-9][A-Za-z0-9._-]*$",
      "type": "string"
    },
    "snapshot_missing": {
      "default": false,
      "type": "boolean"
    },
    "source_checkpoint": {
      "type": [
        "string",
        "null"
      ]
    },
    "superseded_by": {
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "snapshot_id",
    "session_id",
    "bond_id",
    "principal_id",
    "agent_id",
    "profile_id",
    "host_id",
    "profile_ref",
    "policy_owner",
    "policy_rev",
    "effective_policy_rev",
    "source_checkpoint",
    "fork_mode",
    "captured_at",
    "grants",
    "resync"
  ],
  "title": "CHD SessionPolicySnapshot",
  "type": "object"
}
```
